"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["82599"],{27158(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.modelo_formulario.ja_desativado","status":422,"titulo":"O modelo de formul\xe1rio j\xe1 est\xe1 desativado"},"descricao":{"codigo":"uniplus.configuracao.modelo_formulario.ja_desativado","requisitos":[],"oQueAconteceu":["A desativa\xe7\xe3o (`DELETE /api/configuracao/admin/modelos-formulario/{id}`) foi pedida para um modelo de formul\xe1rio que j\xe1 est\xe1 desativado. Isso inclui o modelo rec\xe9m-criado, porque o modelo nasce desativado e s\xf3 entra na escolha dos processos novos quando \xe9 ativado. O modelo n\xe3o \xe9 apagado: desativar apenas o tira da escolha, e os processos que j\xe1 o copiaram n\xe3o mudam. Ao contr\xe1rio de outros cadastros do m\xf3dulo, repetir a desativa\xe7\xe3o n\xe3o \xe9 tratado como sucesso: a opera\xe7\xe3o deixa registro de auditoria, e aceitar uma desativa\xe7\xe3o sem efeito gravaria uma mudan\xe7a que n\xe3o houve.","A busca do modelo vem antes: com um `{id}` que n\xe3o existe, a resposta \xe9 [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado), e s\xf3 um modelo existente chega a esta confer\xeancia. Nada \xe9 gravado."],"comoResolver":["Nenhuma provid\xeancia \xe9 necess\xe1ria: o modelo j\xe1 est\xe1 fora da escolha dos processos novos. Se a inten\xe7\xe3o era outra, confira o identificador do modelo."],"ondeAparece":["Desativa\xe7\xe3o de um modelo de formul\xe1rio"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Modelo formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);